import requests
from collections import defaultdict

# Target server for the DSA crypto challenge
base_url = "http://crypto.chal.csaw.io:5000"

# Function to collect multiple signatures
def collect_signatures(data_samples):
    signatures = []
    for data in data_samples:
        response = requests.get(f"{base_url}/sign/{data}")
        if response.status_code == 200:
            signature = response.json()
            signatures.append((data, signature['r'], signature['s']))
        else:
            print(f"Failed to retrieve signature for data: {data}")
    return signatures

# Analyze signatures for nonce reuse (same 'r' values)
def check_nonce_reuse(signatures):
    r_map = defaultdict(list)
    for data, r, s in signatures:
        r_map[r].append((data, s))

    # Filter entries where 'r' is reused
    reused_r = {r: items for r, items in r_map.items() if len(items) > 1}

    if reused_r:
        print("Nonce reuse detected! Same 'r' values found:")
        for r, items in reused_r.items():
            print(f"r = {r} -> {[data for data, _ in items]}")
    else:
        print("No nonce reuse detected.")

    return reused_r

if __name__ == "__main__":
    # Example input data to collect signatures
    data_samples = [f"data_{i}" for i in range(1, 101)]

    # Collect signatures
    signatures = collect_signatures(data_samples)

    # Check and analyze if the nonce 'k' is reused
    reused_r = check_nonce_reuse(signatures)

    if reused_r:
        # Save the reused data information for further analysis
        with open("reused_nonce_data.json", "w") as f:
            json.dump(reused_r, f)

